package com.dochub.platform.service;

import com.dochub.platform.dto.ApiResponse;
import com.dochub.platform.entity.FileRecord;
import com.dochub.platform.mapper.FileMapper;
import org.springframework.stereotype.Service;
import org.springframework.web.multipart.MultipartFile;

import java.io.IOException;
import java.time.LocalDateTime;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;

/**
 * File use cases: upload (metadata + full bytes persisted in MySQL), fetch a
 * single record including its bytes, and metadata-only listings per document
 * and platform-wide.
 */
@Service
public class FileService {

    private final FileMapper fileMapper;

    public FileService(FileMapper fileMapper) {
        this.fileMapper = fileMapper;
    }

    public ApiResponse<Map<String, Object>> upload(Long docId, MultipartFile file) {
        String originalName = file.getOriginalFilename();
        if (originalName == null || originalName.isBlank()) {
            return ApiResponse.error(400, "文件名无效");
        }
        try {
            FileRecord record = new FileRecord();
            record.setDocId(docId);
            record.setOriginalName(originalName);
            record.setStoredName(generateStoredName(originalName));
            record.setContentType(file.getContentType());
            record.setFileSize(file.getSize());
            record.setFileData(file.getBytes());
            record.setCreatedAt(LocalDateTime.now());
            fileMapper.insert(record);

            Map<String, Object> data = new LinkedHashMap<>();
            data.put("id", record.getId());
            data.put("docId", record.getDocId());
            data.put("originalName", record.getOriginalName());
            data.put("contentType", record.getContentType());
            data.put("fileSize", record.getFileSize());
            data.put("createdAt", record.getCreatedAt());
            return ApiResponse.success("上传成功", data);
        } catch (IOException e) {
            return ApiResponse.error(500, "文件上传失败");
        }
    }

    public FileRecord getById(Long id) {
        if (id == null) {
            return null;
        }
        return fileMapper.findById(id);
    }

    public ApiResponse<List<Map<String, Object>>> listByDocId(Long docId) {
        return ApiResponse.success(toMetadataList(fileMapper.findByDocId(docId)));
    }

    public ApiResponse<List<Map<String, Object>>> listAll() {
        return ApiResponse.success(toMetadataList(fileMapper.findAll()));
    }

    private List<Map<String, Object>> toMetadataList(List<FileRecord> records) {
        List<Map<String, Object>> list = new ArrayList<>(records.size());
        for (FileRecord record : records) {
            Map<String, Object> item = new LinkedHashMap<>();
            item.put("id", record.getId());
            item.put("docId", record.getDocId());
            item.put("originalName", record.getOriginalName());
            item.put("storedName", record.getStoredName());
            item.put("contentType", record.getContentType());
            item.put("fileSize", record.getFileSize());
            item.put("createdAt", record.getCreatedAt());
            list.add(item);
        }
        return list;
    }

    private String generateStoredName(String originalName) {
        String extension = "";
        int dotIndex = originalName.lastIndexOf('.');
        if (dotIndex >= 0) {
            extension = originalName.substring(dotIndex);
        }
        return UUID.randomUUID().toString().replace("-", "") + extension;
    }
}

package com.dochub.platform.util;

import com.dochub.platform.entity.Document;
import com.dochub.platform.entity.User;
import com.dochub.platform.mapper.DocumentMapper;
import com.dochub.platform.mapper.UserMapper;
import org.springframework.boot.CommandLineRunner;
import org.springframework.stereotype.Component;

import java.time.LocalDateTime;

/**
 * Seeds the preset accounts and documents at startup. Each block runs only
 * when the corresponding table is empty, so restarts never duplicate rows.
 */
@Component
public class DataInitializer implements CommandLineRunner {

    private final UserMapper userMapper;
    private final DocumentMapper documentMapper;

    public DataInitializer(UserMapper userMapper, DocumentMapper documentMapper) {
        this.userMapper = userMapper;
        this.documentMapper = documentMapper;
    }

    @Override
    public void run(String... args) {
        if (userMapper.count() == 0) {
            insertUser("admin", "admin123", "ADMIN");
            insertUser("user1", "user123", "USER");
            insertUser("user2", "user456", "USER");
        }

        if (documentMapper.count() == 0) {
            insertDocument("入职指南", "欢迎加入团队...", "user1");
            insertDocument("技术规范", "代码规范文档...", "user1");
            insertDocument("会议纪要", "本周会议内容...", "user2");
        }
    }

    private void insertUser(String username, String password, String role) {
        User user = new User();
        user.setUsername(username);
        user.setPassword(password);
        user.setRole(role);
        user.setCreatedAt(LocalDateTime.now());
        userMapper.insert(user);
    }

    private void insertDocument(String title, String content, String ownerUsername) {
        User owner = userMapper.findByUsername(ownerUsername);
        Document document = new Document();
        document.setTitle(title);
        document.setContent(content);
        document.setUserId(owner.getId());
        document.setCreatedAt(LocalDateTime.now());
        document.setUpdatedAt(LocalDateTime.now());
        documentMapper.insert(document);
    }
}

package com.dochub.platform.util;

import io.jsonwebtoken.Claims;
import io.jsonwebtoken.Jwts;
import io.jsonwebtoken.security.Keys;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

import javax.crypto.SecretKey;
import java.nio.charset.StandardCharsets;
import java.util.Date;

/**
 * Issues and verifies the platform's JWT session tokens. The token embeds the
 * user's id, username and role and is valid for jwt.expiration milliseconds.
 */
@Component
public class JwtUtil {

    @Value("${jwt.secret}")
    private String secret;

    @Value("${jwt.expiration}")
    private Long expiration;

    private SecretKey getSigningKey() {
        return Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));
    }

    public String generateToken(Long userId, String username, String role) {
        Date now = new Date();
        Date expiry = new Date(now.getTime() + expiration);
        return Jwts.builder()
                .claim("userId", userId)
                .claim("username", username)
                .claim("role", role)
                .issuedAt(now)
                .expiration(expiry)
                .signWith(getSigningKey())
                .compact();
    }

    public boolean validateToken(String token) {
        try {
            parseClaims(token);
            return true;
        } catch (Exception e) {
            return false;
        }
    }

    public Long getUserId(String token) {
        Object value = parseClaims(token).get("userId");
        if (value instanceof Number number) {
            return number.longValue();
        }
        return Long.valueOf(String.valueOf(value));
    }

    public String getUsername(String token) {
        return parseClaims(token).get("username", String.class);
    }

    public String getRole(String token) {
        return parseClaims(token).get("role", String.class);
    }

    private Claims parseClaims(String token) {
        return Jwts.parser()
                .verifyWith(getSigningKey())
                .build()
                .parseSignedClaims(token)
                .getPayload();
    }
}
